input.command:
python3 plugins/dev-graph/scripts/build-graph-node.py update --repo-root "$PWD" --input .dev-graph/cache/sync-run1/issue-update-input-1.json > $TMPDIR/apply.json; echo rc=$?; python3 -c "
import json;d=json.load(open('$TMPDIR/apply.json'))
for k in ['status','valid','applied_count','write_count','graph_revision_before','graph_revision_after','graph_digest_after','receipt_path','input_sha256','pre_write_validation']: print(k,d.get(k))
print(d['artifacts'][0]['sha256_after'], d['artifacts'][0]['node_fields_patched'])
"; ls .dev-graph/state/receipts/ | tail -3; python3 -c "import json;g=json.load(open('.dev-graph/state/graph.json'));print('graph rev', g.get('graph_revision', g.get('revision')))"

